function renderServices() { document.getElementById('service-list').innerHTML = state.services.map(service => `<div class="service-row"><span class="service-name"><i class="service-bullet"></i>${safe(service.nama_layanan)}</span><span class="service-price">${currency.format(service.harga_standar)}</span></div>`).join('') || '<p class="muted">Belum ada layanan.</p>'; }
function renderChart() {
  const days = Number(document.getElementById('period-filter').value);
  const end = new Date();
  const points = [];
  for (let index = days - 1; index >= 0; index -= 1) {
    const date = new Date(end);
    date.setDate(end.getDate() - index);
    const key = dateKey(date);
    points.push({
      key,
      label: new Intl.DateTimeFormat('id-ID', { day: '2-digit', month: 'short' }).format(date),
      value: state.incomes.filter(row => row.tanggal === key).reduce((sum, row) => sum + Number(row.total), 0)
    });
  }

  const chart = document.getElementById('income-chart');
  const width = document.querySelector('.chart-area').clientWidth || 700;
  const height = chart.clientHeight || 265;
  const max = Math.max(...points.map(point => point.value), 1);
  const coords = points.map((point, index) => ({
    x: (index / Math.max(points.length - 1, 1)) * width,
    y: height - 10 - (point.value / max) * (height - 45)
  }));
  const segments = coords.slice(0, -1).map((point, index) => {
    const next = coords[index + 1];
    const midpoint = (point.x + next.x) / 2;
    return `C ${midpoint},${point.y} ${midpoint},${next.y} ${next.x},${next.y}`;
  }).join(' ');
  const line = `M ${coords[0].x},${coords[0].y} ${segments}`;

  chart.setAttribute('viewBox', `0 0 ${width} ${height}`);
  document.getElementById('chart-line').setAttribute('d', line);
  document.getElementById('chart-area-fill').setAttribute('d', `${line} L ${width},${height} L 0,${height} Z`);
  document.getElementById('chart-points').innerHTML = coords
    .map(point => `<circle class="chart-pulse" cx="${point.x}" cy="${point.y}" r="4"/>`)
    .join('');
  document.getElementById('chart-labels').innerHTML = points
    .filter((_, index) => index === 0 || index === Math.floor(points.length / 2) || index === points.length - 1)
    .map(point => `<span>${point.label}</span>`)
    .join('');
}
