document.getElementById('service-id').addEventListener('change', event => { setIncomeAmountFromService(event.target.value); });
saveMaster('customer-form', '/pelanggan', 'customer-message'); saveMaster('vehicle-form', '/kendaraan', 'vehicle-message'); saveMaster('service-form', '/layanan', 'service-message');
document.getElementById('period-filter').addEventListener('change', renderChart); document.getElementById('today-label').textContent = new Intl.DateTimeFormat('id-ID', { dateStyle: 'full' }).format(new Date()); document.getElementById('income-date').value = today(); loadData().then(() => { fillQueueFormOptions(); loadOperations(); reportRows(); }); setInterval(refreshIncomeActivity, 15000); document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') refreshIncomeActivity(); });
window.addEventListener('hashchange', () => { setPage(window.location.hash.slice(1)); if (document.body.dataset.page === 'dashboard') renderChart(); }); setPage(window.location.hash.slice(1) || 'dashboard');

const dateKey = value => { const date = value instanceof Date ? value : new Date(value); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`; };
const safe = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const queueDate = item => dateKey(item.jadwal_mulai);
function updateOperationalMetrics() { const day = today(); document.getElementById('working-count').textContent = state.queue.filter(item => item.status === 'dikerjakan').length; document.getElementById('waiting-count').textContent = state.queue.filter(item => item.status === 'menunggu' && queueDate(item) === day).length; }
function renderCalendar() { const cursor = state.calendarCursor; const year = cursor.getFullYear(); const month = cursor.getMonth(); document.getElementById('calendar-month').textContent = new Intl.DateTimeFormat('id-ID', { month: 'long', year: 'numeric' }).format(cursor); const first = new Date(year, month, 1); const startOffset = (first.getDay() + 6) % 7; const daysCount = new Date(year, month + 1, 0).getDate(); const counts = {}; state.queue.forEach(item => { const key = queueDate(item); if (item.status !== 'dipanggil') counts[key] = (counts[key] || 0) + 1; }); const cells = Array.from({ length: startOffset }, () => '<button class="blank" tabindex="-1"></button>'); for (let day = 1; day <= daysCount; day += 1) { const key = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`; const count = counts[key] || 0; const density = count >= 6 ? 'high' : count >= 3 ? 'medium' : 'low'; const classes = [`density-${density}`, key === today() ? 'today' : '', key === state.selectedCalendarDate ? 'selected' : ''].filter(Boolean).join(' '); cells.push(`<button class="${classes}" data-calendar-date="${key}" title="${count} unit terjadwal">${day}${count ? `<small>${count}</small>` : ''}</button>`); } document.getElementById('calendar-days').innerHTML = cells.join(''); renderSelectedDay(); }
function renderSelectedDay() { const key = state.selectedCalendarDate; const selected = new Date(`${key}T12:00:00`); const count = state.queue.filter(item => queueDate(item) === key && item.status !== 'dipanggil').length; const status = count >= 6 ? 'Penuh / ramai' : count >= 3 ? 'Sedang' : 'Low / tersedia'; document.getElementById('selected-day-title').textContent = new Intl.DateTimeFormat('id-ID', { weekday: 'long', day: 'numeric', month: 'long' }).format(selected); document.getElementById('selected-day-detail').textContent = `${status} · kapasitas operasional 8 unit per hari`; document.getElementById('selected-day-count').textContent = `${count} unit terjadwal`; const fill = document.getElementById('capacity-fill'); fill.style.width = `${Math.min(count / 8 * 100, 100)}%`; fill.style.background = count >= 6 ? '#ca6555' : count >= 3 ? '#dda93f' : '#67a778'; }
function phoneNumber(phone) { let digits = String(phone || '').replace(/\D/g, ''); if (digits.startsWith('0')) digits = `62${digits.slice(1)}`; return digits; }
function whatsappLink(item, message) { return `https://wa.me/${phoneNumber(item.pelanggan?.no_telepon)}?text=${encodeURIComponent(message)}`; }
function callCustomer(item) { const overlay = document.createElement('div'); overlay.className = 'call-screen'; overlay.innerHTML = `<div><p class="eyebrow">PANGGILAN PELANGGAN</p><strong>${safe(item.nomor_tiket)}</strong><h2>${safe(item.pelanggan?.nama)}</h2><p>${safe(item.kendaraan?.nomor_polisi)} · silakan menuju loket</p><button type="button">Tutup</button></div>`; overlay.querySelector('button').addEventListener('click', () => overlay.remove()); document.body.append(overlay); if ('speechSynthesis' in window) { const utterance = new SpeechSynthesisUtterance(`Nomor antrean ${item.nomor_tiket}. ${item.pelanggan?.nama}, silakan menuju loket.`); utterance.lang = 'id-ID'; window.speechSynthesis.speak(utterance); } }
function statusButton(item) { if (item.status === 'menunggu') return `<button data-queue-status="dikerjakan" data-queue-id="${safe(item.id)}">Mulai pengerjaan</button>`; if (item.status === 'dikerjakan') return `<button data-queue-status="selesai" data-queue-id="${safe(item.id)}">Tandai selesai</button>`; if (item.status === 'selesai') return `<button data-call-id="${safe(item.id)}">Panggil pelanggan</button>`; return '<span class="queue-status">Sudah dipanggil</span>'; }
function renderQueueCard(item) { const estimateHours = Number(item.layanan?.estimasi_jam || 1); const started = item.waktu_mulai ? new Date(item.waktu_mulai) : null; const eta = started ? new Date(started.getTime() + estimateHours * 3600000) : null; const remaining = eta ? Math.max(0, eta - Date.now()) : 0; const timeText = started ? remaining ? `Sisa ${Math.floor(remaining / 3600000)}j ${Math.floor(remaining % 3600000 / 60000)}m` : 'Lewat estimasi' : `Estimasi ${estimateHours} jam`; const message = `Halo ${item.pelanggan?.nama}, pengerjaan ${item.kendaraan?.nomor_polisi} (${item.layanan?.nama_layanan}) sudah selesai dan siap diambil di Press Body Motor. Tiket ${item.nomor_tiket}.`; const wa = whatsappLink(item, message); return `<article class="queue-card status-${safe(item.status)}"><div class="queue-card-top"><strong>${safe(item.nomor_tiket)}</strong><span class="queue-status">${safe(item.status)}</span></div><p><b>${safe(item.pelanggan?.nama)}</b> · ${safe(item.kendaraan?.nomor_polisi)} (${safe(item.kendaraan?.merk)} ${safe(item.kendaraan?.tipe)})</p><div class="queue-card-meta"><span>${safe(item.layanan?.nama_layanan)}</span><span>${timeText}</span><span>${new Intl.DateTimeFormat('id-ID', { hour: '2-digit', minute: '2-digit' }).format(new Date(item.jadwal_mulai))}</span></div><div class="queue-card-actions">${statusButton(item)}${item.status === 'selesai' ? `<a href="${wa}" target="_blank" rel="noreferrer">Kirim WhatsApp</a>` : ''}</div></article>`; }
function renderQueues() { const nowKey = today(); const relevant = state.queue.filter(item => queueDate(item) >= nowKey && item.status !== 'dipanggil'); const bookings = relevant.filter(item => item.tipe_kedatangan === 'booking'); const walkins = relevant.filter(item => item.tipe_kedatangan === 'walk-in' && queueDate(item) === nowKey); document.getElementById('booking-count').textContent = bookings.length; document.getElementById('walkin-count').textContent = walkins.length; document.getElementById('booking-list').innerHTML = bookings.map(renderQueueCard).join('') || '<div class="queue-empty">Belum ada booking mendatang.</div>'; document.getElementById('walkin-list').innerHTML = walkins.map(renderQueueCard).join('') || '<div class="queue-empty">Belum ada unit walk-in hari ini.</div>'; document.querySelectorAll('[data-queue-status]').forEach(button => button.addEventListener('click', async () => { button.disabled = true; try { await api(`/antrian/${button.dataset.queueId}`, { method: 'PATCH', body: JSON.stringify({ status: button.dataset.queueStatus }) }); await loadOperations(); } catch (error) { button.disabled = false; alert(error.message); } })); document.querySelectorAll('[data-call-id]').forEach(button => button.addEventListener('click', async () => { const item = state.queue.find(entry => entry.id === button.dataset.callId); if (!item) return; try { await api(`/antrian/${item.id}`, { method: 'PATCH', body: JSON.stringify({ status: 'dipanggil' }) }); callCustomer(item); await loadOperations(); } catch (error) { alert(error.message); } })); const completed = state.queue.filter(item => item.status === 'selesai').slice(0, 3); document.getElementById('completed-alert').innerHTML = completed.length ? `<p class="eyebrow">SIAP DIPANGGIL</p>${completed.map(item => `<div class="alert-line"><span><b>${safe(item.nomor_tiket)}</b> · ${safe(item.pelanggan?.nama)} · ${safe(item.kendaraan?.nomor_polisi)}</span><button data-quick-call="${safe(item.id)}">Panggil ↗</button></div>`).join('')}` : '<p class="muted">Belum ada unit selesai yang menunggu panggilan.</p>'; document.querySelectorAll('[data-quick-call]').forEach(button => button.addEventListener('click', async () => { const item = state.queue.find(entry => entry.id === button.dataset.quickCall); if (!item) return; callCustomer(item); await api(`/antrian/${item.id}`, { method: 'PATCH', body: JSON.stringify({ status: 'dipanggil' }) }); await loadOperations(); })); updateOperationalMetrics(); renderCalendar(); renderCashQueueOptions(); }
function renderCashQueueOptions() { const select = document.getElementById('cash-queue-source'); if (!select) return; const alreadyPaid = new Set(state.incomes.map(row => row.antrian_id).filter(Boolean)); const completed = state.queue.filter(item => ['selesai', 'dipanggil'].includes(item.status) && !alreadyPaid.has(item.id)); select.innerHTML = '<option value="">Pilih tiket selesai</option>' + completed.map(item => `<option value="${safe(item.id)}">${safe(item.nomor_tiket)} · ${safe(item.pelanggan?.nama)} · ${safe(item.kendaraan?.nomor_polisi)}</option>`).join(''); }
async function loadOperations() { try { state.queue = await api('/antrian'); state.queueReady = true; renderQueues(); renderManagedRecords(); } catch (error) { state.queue = []; state.queueReady = false; renderQueues(); renderManagedRecords(); document.getElementById('booking-list').innerHTML = '<div class="queue-empty">Fitur booking belum aktif. Jalankan database/operational-features.sql di Supabase, lalu refresh aplikasi.</div>'; updateOperationalMetrics(); } }
function localDateTime(date = new Date()) { const pad = value => String(value).padStart(2, '0'); return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`; }
function fillQueueFormOptions() { fillSelect('queue-customer', state.customers, 'pelanggan'); fillSelect('queue-vehicle', [], 'kendaraan'); fillSelect('queue-service', state.services, 'layanan'); }
