document.getElementById('book-selected-day').addEventListener('click', () => { location.hash = '#layanan'; document.getElementById('arrival-type').value = 'booking'; document.getElementById('queue-datetime').value = `${state.selectedCalendarDate}T09:00`; document.getElementById('queue-datetime-label').firstChild.textContent = 'Jadwal booking'; setTimeout(() => document.getElementById('queue-form').scrollIntoView({ behavior: 'smooth', block: 'center' }), 120); });
