document.getElementById('queue-form').addEventListener('submit', async event => { event.preventDefault(); const form = event.currentTarget; if (form.dataset.submitting === 'true') return; setFormBusy(form, true); const message = document.getElementById('queue-message'); message.textContent = ''; const data = Object.fromEntries(new FormData(form)); data.jadwal_mulai = new Date(data.jadwal_mulai).toISOString(); try { const inserted = await api('/antrian', { method: 'POST', body: JSON.stringify(data) }); form.reset(); document.getElementById('queue-datetime').value = localDateTime(); fillQueueFormOptions(); message.style.color = '#3d9863'; message.textContent = `Nomor antrean ${inserted[0]?.nomor_tiket || 'berhasil dibuat'}.`; await loadOperations(); } catch (error) { message.style.color = 'var(--red)'; message.textContent = error.message; } finally { setFormBusy(form, false); } });
function reportRows() { const period = document.getElementById('report-period').value; const method = document.getElementById('report-method').value; const date = document.getElementById('report-date').value || today(); const selected = new Date(`${date}T12:00:00`); const from = new Date(selected); if (period === 'weekly') from.setDate(from.getDate() - 6); const rows = state.incomes.filter(row => { const key = row.tanggal; const dateMatch = period === 'all' || (period === 'daily' && key === date) || (period === 'weekly' && key >= dateKey(from) && key <= date) || (period === 'monthly' && key.slice(0, 7) === date.slice(0, 7)); return dateMatch && (method === 'all' || row.metode_pembayaran === method); }); document.getElementById('report-total').textContent = currency.format(rows.reduce((total, row) => total + Number(row.total), 0)); document.getElementById('report-rows').innerHTML = rows.map(row => `<tr><td>${safe(row.tanggal)}</td><td>${safe(row.nomor_transaksi)}</td><td>${safe(row.pelanggan?.nama || '-')}</td><td>${safe(row.metode_pembayaran || '-')}</td><td class="align-right amount">${currency.format(row.total)}<button class="receipt-link" data-receipt-id="${safe(row.id)}" type="button" aria-label="Lihat struk transaksi ${safe(row.nomor_transaksi)}">Struk</button></td></tr>`).join('') || '<tr><td colspan="5" class="empty-state">Tidak ada transaksi sesuai filter.</td></tr>'; return rows; }
function downloadReport() { const rows = reportRows(); const csv = [['Tanggal', 'Nomor Transaksi', 'Pelanggan', 'Metode Pembayaran', 'Total'], ...rows.map(row => [row.tanggal, row.nomor_transaksi, row.pelanggan?.nama || '', row.metode_pembayaran || '', row.total])].map(line => line.map(value => `"${String(value).replace(/"/g, '""')}"`).join(',')).join('\r\n'); const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob(['\ufeff', csv], { type: 'text/csv;charset=utf-8' })); link.download = `laporan-pendapatan-${today()}.csv`; link.click(); URL.revokeObjectURL(link.href); }
function printPage(title, content, pageCss = '') { const popup = window.open('', '_blank', 'width=520,height=720'); if (!popup) return alert('Izinkan pop-up untuk mencetak nota/laporan.'); popup.document.write(`<!doctype html><html><head><title>${safe(title)}</title><style>body{font:12px Arial,sans-serif;margin:18px;color:#111}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:6px;border-bottom:1px solid #ddd}.right{text-align:right}.invoice-body{width:100%;max-width:520px;margin:0 auto;padding:22px;border:1px solid #d8d5ca;border-top:4px solid #ff951e;border-radius:10px;background:#fffefa;color:#1b2b23;font:13px Arial,sans-serif;box-sizing:border-box}.invoice-header{text-align:center;padding:2px 0 17px;border-bottom:1px solid #d8d5ca}.invoice-logo{display:block;width:56px;height:56px;object-fit:contain;margin:0 auto 10px;padding:4px;border:1px solid #ead6a8;border-radius:15px;background:#f0f4ed}.invoice-header h1{margin:0;color:#17382e;font-size:17px;letter-spacing:.055em}.invoice-header p,.invoice-thanks{margin:6px 0 0;color:#63736a;font-size:12px}.invoice-details{display:grid;gap:0;margin:14px 0}.invoice-details p{display:flex;justify-content:space-between;gap:12px;margin:0;padding:10px 0;border-bottom:1px solid #e2dfd5}.invoice-details span{color:#69786f}.invoice-details strong{min-width:0;overflow-wrap:anywhere;text-align:right;font-weight:600}.invoice-total{display:flex;justify-content:space-between;gap:12px;margin:0;padding:14px 0;border-top:1px dashed #aeb9af;border-bottom:1px dashed #aeb9af;color:#17382e;font-weight:700}.invoice-total strong{color:#17382e;font-size:17px;text-align:right}.invoice-thanks{text-align:center;margin:16px 0 0}@page{${pageCss}}</style></head><body>${content}<script>window.onload=()=>window.print()<\/script></body></html>`); popup.document.close(); }
function receiptHtml(item) { const logoUrl = new URL('logo/logo-emblem%20(1).png', location.href).href; return `<article class="invoice-body"><header class="invoice-header"><img class="invoice-logo" src="${safe(logoUrl)}" alt="Logo Press Body Motor"><h1>PRESS BODY MOTOR</h1><p>Bukti pembayaran jasa bengkel</p></header><div class="invoice-details"><p><span>No. transaksi</span><strong>${safe(item.nomor_transaksi)}</strong></p><p><span>Tanggal</span><strong>${safe(item.tanggal)}</strong></p><p><span>Pelanggan</span><strong>${safe(item.pelangganName)}</strong></p><p><span>Kendaraan</span><strong>${safe(item.plate)}</strong></p><p><span>Layanan</span><strong>${safe(item.serviceName)}</strong></p><p><span>Metode pembayaran</span><strong>${safe(item.method)}</strong></p></div><div class="invoice-total"><span>Total pembayaran</span><strong>${currency.format(item.total)}</strong></div><p class="invoice-thanks">Terima kasih atas kepercayaan Anda.</p></article>`; }
function receiptFromIncome(row) { const customer = state.customers.find(entry => entry.id === row.pelanggan_id); const vehicle = state.vehicles.find(entry => entry.id === row.kendaraan_id); const service = state.services.find(entry => entry.id === row.layanan_id); return { ...row, total: Number(row.total ?? row.subtotal ?? 0), pelangganName: row.pelanggan?.nama || customer?.nama || '-', customerPhone: customer?.no_telepon || row.pelanggan?.no_telepon || '', plate: vehicle?.nomor_polisi || row.kendaraan?.nomor_polisi || '-', serviceName: row.layanan?.nama_layanan || service?.nama_layanan || '-', method: row.metode_pembayaran || '-' }; }
function openReceipt(transactionId) { const row = state.incomes.find(entry => String(entry.id) === String(transactionId)); if (!row) return alert('Transaksi tidak ditemukan. Muat ulang data lalu coba lagi.'); state.currentReceipt = receiptFromIncome(row); document.getElementById('receipt-preview').innerHTML = receiptHtml(state.currentReceipt); document.getElementById('receipt-dialog').showModal(); }
function printCurrentReceipt() { const item = state.currentReceipt; if (!item) return alert('Pilih transaksi dari riwayat terlebih dahulu.'); const format = document.getElementById('receipt-format').value; const page = format === 'pdf' ? 'size: A4; margin: 14mm' : `size: ${format === 'thermal80' ? '80mm' : '58mm'} 200mm; margin: 4mm`; printPage(`Nota ${item.nomor_transaksi} - Press Body Motor`, receiptHtml(item), page); }
