const originalIncomeSubmit = document.getElementById('income-form');
originalIncomeSubmit.addEventListener('submit', async event => { event.preventDefault(); const form = event.currentTarget; if (form.dataset.submitting === 'true') return; setFormBusy(form, true); const message = document.getElementById('form-message'); message.textContent = ''; const payload = { pelanggan_id: document.getElementById('customer-id').value, kendaraan_id: document.getElementById('vehicle-id').value, layanan_id: document.getElementById('service-id').value, total: Number(document.getElementById('amount').value), tanggal: document.getElementById('income-date').value, metode_pembayaran: document.getElementById('payment-method').value }; try { await api('/pendapatan', { method: 'POST', body: JSON.stringify(payload) }); form.reset(); document.getElementById('income-date').value = today(); document.getElementById('payment-method').value = 'tunai'; message.style.color = '#3d9863'; message.textContent = 'Transaksi tersimpan. Struk tersedia di riwayat transaksi.'; await loadData(); await loadOperations(); reportRows(); } catch (error) { message.style.color = 'var(--red)'; message.textContent = error.message; } finally { setFormBusy(form, false); } });
